package com.profa.course;import jakarta.persistence.*;import java.time.*;import java.util.*;@Entity @Table(name="course_requests")public class CourseRequest{@Id@GeneratedValue(strategy=GenerationType.UUID)UUID id;UUID parentId;UUID teacherId;String subject;String level;String mode;String city;String district;Integer budget;String scheduleJson;String status="PENDING";String notes;Instant createdAt=Instant.now();public UUID getId(){return id;}public UUID getParentId(){return parentId;}public void setParentId(UUID v){parentId=v;}public UUID getTeacherId(){return teacherId;}public void setTeacherId(UUID v){teacherId=v;}public String getSubject(){return subject;}public void setSubject(String v){subject=v;}public String getLevel(){return level;}public void setLevel(String v){level=v;}public String getMode(){return mode;}public void setMode(String v){mode=v;}public String getCity(){return city;}public void setCity(String v){city=v;}public String getDistrict(){return district;}public void setDistrict(String v){district=v;}public Integer getBudget(){return budget;}public void setBudget(Integer v){budget=v;}public String getScheduleJson(){return scheduleJson;}public void setScheduleJson(String v){scheduleJson=v;}public String getStatus(){return status;}public void setStatus(String v){status=v;}public String getNotes(){return notes;}public void setNotes(String v){notes=v;}}